#include <lc3.h>

#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <assert.h>

static const char *log_pcm0 =
"";

static const char *log_pcm1 =
"";

static const char *log_pcm2 =
"";

static void conv_log(const char *s, int16_t *v, int n)
{
    int len = strlen(s) / 4;
    assert(len == n);

    memset(v, 0, n * sizeof(int16_t));

    for (int i = 0; i < 4*len; i++) {
        int d = (isalpha(s[i]) ? 10 + (tolower(s[i]) - 'a') : s[i] - '0');
        v[i/4] |= d << (4 * (3 - (i % 4)));
    }
}

int main()
{
    int frame_us = 10000;
    int sr_hz = 48000;
    int16_t pcm0[480], pcm1[480], pcm2[480];

    conv_log(log_pcm0, pcm0, 480);
    conv_log(log_pcm1, pcm1, 480);
    conv_log(log_pcm2, pcm2, 480);

    printf("-- lc3_encoder_size: %d\n", lc3_encoder_size(frame_us, sr_hz));

    lc3_encoder_t enc_left = lc3_setup_encoder(
        frame_us, sr_hz, malloc(lc3_encoder_size(frame_us, sr_hz)));

    lc3_encoder_t enc_right = lc3_setup_encoder(
        frame_us, sr_hz, malloc(lc3_encoder_size(frame_us, sr_hz)));

    int encoded_size = 120;
    unsigned char out[encoded_size];

    printf("-- encode left \n");
    lc3_encode(enc_left, pcm0, 1, out, encoded_size);
    printf("-- out: [%02x %02x .. %02x %02x]\n",
        out[0], out[1], out[encoded_size-2], out[encoded_size-1]);

    printf("-- encode left \n");
    lc3_encode(enc_left, pcm1, 1, out, encoded_size);
    printf("-- out: [%02x %02x .. %02x %02x]\n",
        out[0], out[1], out[encoded_size-2], out[encoded_size-1]);


    printf("-- encode left \n");
    lc3_encode(enc_left, pcm2, 1, out, encoded_size);
    printf("-- out: [%02x %02x .. %02x %02x]\n",
        out[0], out[1], out[encoded_size-2], out[encoded_size-1]);

    printf("-- done \n");

    free(enc_left);
    free(enc_right);
}